INSERT INTO public.section_settings
  (section_key, label, eyebrow_translations, title_translations, highlight_translations, description_translations, is_visible, display_order)
VALUES
  ('services', 'Services', '{"en": "Services", "de": "Leistungen", "fr": "Services", "es": "Servicios"}'::jsonb, '{"en": "Our Core", "de": "Unsere Kernleistungen", "fr": "Nos Services Principaux", "es": "Nuestros Servicios Principales"}'::jsonb, '{"en": "Services", "de": "", "fr": "", "es": ""}'::jsonb, '{"en": "Strategic solutions engineered to scale your digital presence with precision and luxury.", "de": "Strategische Lösungen, die Ihre digitale Präsenz präzise und hochwertig skalieren.", "fr": "Des solutions stratégiques conçues pour développer votre présence numérique avec précision et luxe.", "es": "Soluciones estratégicas diseñadas para escalar su presencia digital con precisión y lujo."}'::jsonb, true, 10),
  ('process', 'Process', '{"en": "Process", "de": "Prozess", "fr": "Processus", "es": "Proceso"}'::jsonb, '{"en": "How We", "de": "Wie wir", "fr": "Comment nous", "es": "Cómo"}'::jsonb, '{"en": "Work", "de": "arbeiten", "fr": "travaillons", "es": "trabajamos"}'::jsonb, '{"en": "A proven framework that takes you from idea to scale with clarity, efficiency, and predictability.", "de": "Ein bewährter Prozess, der Sie klar, effizient und planbar von der Idee zur Skalierung führt.", "fr": "Une méthode éprouvée qui vous accompagne de l'idée à la croissance avec clarté, efficacité et maîtrise.", "es": "Un método probado que le lleva de la idea al crecimiento de forma clara, eficiente y predecible."}'::jsonb, true, 20),
  ('why-choose-us', 'Why Choose Us', '{"en": "Why Us", "de": "Warum wir", "fr": "Pourquoi nous choisir", "es": "Por qué elegirnos"}'::jsonb, '{"en": "Not Just Another", "de": "Mehr als eine", "fr": "Pas une", "es": "No somos una"}'::jsonb, '{"en": "Agency", "de": "Agentur", "fr": "agence comme les autres", "es": "agencia más"}'::jsonb, '{"en": "We build strategic digital assets that strengthen your market position and create lasting business value.", "de": "Wir entwickeln strategische digitale Lösungen, die Ihre Marktposition stärken und nachhaltigen Unternehmenswert schaffen.", "fr": "Nous créons des actifs numériques stratégiques qui renforcent votre position sur le marché et génèrent une valeur durable pour votre entreprise.", "es": "Creamos activos digitales estratégicos que refuerzan su posición en el mercado y generan valor empresarial duradero."}'::jsonb, true, 30),
  ('insights', 'Insights & Expertise', '{"en": "Insights", "de": "Einblicke", "fr": "Analyses", "es": "Perspectivas"}'::jsonb, '{"en": "Ideas for Smarter", "de": "Impulse für intelligentes", "fr": "Des idées pour accélérer votre", "es": "Ideas para un crecimiento"}'::jsonb, '{"en": "Digital Growth", "de": "digitales Wachstum", "fr": "croissance numérique", "es": "digital más inteligente"}'::jsonb, '{"en": "Thought leadership, industry perspectives, and actionable strategies from our team of strategists, designers, and engineers.", "de": "Thought Leadership, Branchenperspektiven und umsetzbare Strategien von unserem Team aus Strategen, Designern und Ingenieuren.", "fr": "Leadership éclairé, perspectives sectorielles et stratégies concrètes de notre équipe de stratèges, designers et ingénieurs.", "es": "Liderazgo de pensamiento, perspectivas de la industria y estrategias accionables de nuestro equipo de estrategas, diseñadores e ingenieros."}'::jsonb, true, 40),
  ('portfolio', 'Portfolio', '{"en": "Portfolio", "de": "Portfolio", "fr": "Portfolio", "es": "Portafolio"}'::jsonb, '{"en": "Our", "de": "Unsere", "fr": "Nos", "es": "Nuestros"}'::jsonb, '{"en": "Work", "de": "Arbeiten", "fr": "Réalisations", "es": "Proyectos"}'::jsonb, '{"en": "We craft digital experiences that define industries and elevate brands through precision and creativity.", "de": "Wir gestalten digitale Erlebnisse, die Branchen definieren und Marken durch Präzision und Kreativität aufwerten.", "fr": "Nous créons des expériences numériques qui définissent les industries et élèvent les marques grâce à la précision et la créativité.", "es": "Creamos experiencias digitales que definen industrias y elevan marcas a través de la precisión y la creatividad."}'::jsonb, true, 50),
  ('testimonials', 'Testimonials', '{"en": "Testimonials", "de": "Kundenstimmen", "fr": "Témoignages", "es": "Testimonios"}'::jsonb, '{"en": "What Our Clients", "de": "Das sagen unsere Kunden", "fr": "Ce que disent nos clients", "es": "Lo que dicen nuestros clientes"}'::jsonb, '{"en": "Say", "de": "", "fr": "", "es": ""}'::jsonb, '{"en": "Don''t take our word for it — hear from the brands we''ve helped scale.", "de": "Erfahren Sie direkt von unseren Kunden, wie sie die Zusammenarbeit mit STRATIFIT erlebt haben.", "fr": "Découvrez directement l''expérience des clients qui ont travaillé avec STRATIFIT.", "es": "Conozca directamente la experiencia de los clientes que han trabajado con STRATIFIT."}'::jsonb, true, 60),
  ('pricing', 'Pricing', '{"en": "Pricing", "de": "Preise", "fr": "Tarifs", "es": "Precios"}'::jsonb, '{"en": "Service", "de": "Leistungs", "fr": "Offres de", "es": "Paquetes de"}'::jsonb, '{"en": "Packages", "de": "pakete", "fr": "services", "es": "servicios"}'::jsonb, '{"en": "Clear starting prices for every stage of growth. Final scope, timeline, and investment are confirmed after discovery.", "de": "Klare Startpreise für jede Wachstumsphase. Leistungsumfang, Zeitrahmen und Investition werden nach der Analyse verbindlich festgelegt.", "fr": "Des tarifs de départ clairs pour chaque phase de croissance. Le périmètre, le calendrier et l’investissement définitifs sont confirmés après la phase de découverte.", "es": "Precios iniciales claros para cada etapa de crecimiento. El alcance, el plazo y la inversión definitivos se confirman después de la fase de descubrimiento."}'::jsonb, true, 70),
  ('faq', 'FAQ', '{"en": "Support", "de": "Support", "fr": "Assistance", "es": "Ayuda"}'::jsonb, '{"en": "Frequently Asked", "de": "Häufig gestellte", "fr": "Questions", "es": "Preguntas"}'::jsonb, '{"en": "Questions", "de": "Fragen", "fr": "fréquentes", "es": "frecuentes"}'::jsonb, '{"en": "Clear answers to common questions about our process, pricing, technology, and ongoing support.", "de": "Klare Antworten auf häufige Fragen zu unserer Arbeitsweise, unseren Preisen, Technologien und Supportleistungen.", "fr": "Des réponses claires aux questions fréquentes concernant notre méthode, nos tarifs, nos technologies et notre accompagnement.", "es": "Respuestas claras a preguntas frecuentes sobre nuestro proceso, precios, tecnología y soporte continuo."}'::jsonb, true, 80),
  ('contact', 'Contact', '{"en": "Contact", "de": "Kontakt", "fr": "Contact", "es": "Contacto"}'::jsonb, '{"en": "Let''s Talk", "de": "Sprechen wir über Ihr Projekt", "fr": "Parlons de votre projet", "es": "Hablemos de su proyecto"}'::jsonb, '{}'::jsonb, '{"en": "Ready to move your project forward? Tell us about your goals, challenges, and timeline. We''ll respond within one business day.", "de": "Möchten Sie Ihr Projekt voranbringen? Erzählen Sie uns von Ihren Zielen, Herausforderungen und Ihrem Zeitrahmen. Wir antworten innerhalb eines Werktages.", "fr": "Vous souhaitez faire avancer votre projet ? Présentez-nous vos objectifs, vos défis et votre calendrier. Nous vous répondrons sous un jour ouvré.", "es": "¿Está listo para impulsar su proyecto? Cuéntenos sus objetivos, desafíos y plazos. Responderemos en un día laborable."}'::jsonb, true, 95)
ON CONFLICT (section_key) DO UPDATE SET
  label = EXCLUDED.label,
  eyebrow_translations = EXCLUDED.eyebrow_translations,
  title_translations = EXCLUDED.title_translations,
  highlight_translations = EXCLUDED.highlight_translations,
  description_translations = EXCLUDED.description_translations,
  is_visible = EXCLUDED.is_visible,
  display_order = EXCLUDED.display_order;

