INSERT INTO public.services (slug, title_translations, short_description_translations, full_description_translations, deliverables_translations, icon_name, cta_label_translations, cta_url, display_order, is_featured, is_visible, status)
VALUES
  ('brand-design',
   '{"en": "Brand Design", "de": "Markendesign", "fr": "Design de marque", "es": "Diseño de marca"}'::jsonb,
   '{"en": "Distinctive brand systems designed to build credibility, sharpen your positioning, and make your business memorable.", "de": "Unverwechselbare Markensysteme, die Vertrauen schaffen, Ihre Positionierung schärfen und Ihre Marke im Gedächtnis verankern.", "fr": "Des identités de marque distinctives conçues pour renforcer votre crédibilité, affirmer votre positionnement et rendre votre entreprise mémorable.", "es": "Identidades de marca distintivas diseñadas para reforzar su credibilidad, definir su posicionamiento y hacer que su empresa sea memorable."}'::jsonb,
   '{"en": "We create comprehensive brand systems that resonate with your audience and stand out in the market.", "de": "Wir erstellen umfassende Markensysteme, die bei Ihrer Zielgruppe ankommen und sich am Markt abheben.", "fr": "Nous créons des systèmes de marque complets qui résonnent avec votre public et se démarquent sur le marché.", "es": "Creamos sistemas de marca completos que resuenan con tu audiencia y destacan en el mercado."}'::jsonb,
   '{"en": ["Brand Strategy", "Logo Design", "Visual Identity System", "Color & Typography System"], "de": ["Markenstrategie", "Logodesign", "Visuelles Markensystem", "Farb- und Typografiesystem"], "fr": ["Stratégie de marque", "Création de logo", "Système d’identité visuelle", "Palette de couleurs et typographie"], "es": ["Estrategia de marca", "Diseño de logotipo", "Sistema de identidad visual", "Sistema de color y tipografía"]}'::jsonb,
   'Palette',
   '{"en": "Learn More", "de": "Mehr erfahren", "fr": "En savoir plus", "es": "Saber más"}'::jsonb,
   '/contact',
   1,
   true,
   true,
   'published'
  ),
  ('website-development',
   '{"en": "Web Development", "de": "Webentwicklung", "fr": "Développement web", "es": "Desarrollo web"}'::jsonb,
   '{"en": "High-performance websites and web applications engineered for speed, scalability, and conversion.", "de": "Leistungsstarke Websites und Webanwendungen, optimiert für Geschwindigkeit, Skalierbarkeit und hohe Conversion-Raten.", "fr": "Des sites et applications web performants, optimisés pour la rapidité, l’évolutivité et la conversion.", "es": "Sitios y aplicaciones web de alto rendimiento, diseñados para ofrecer velocidad, escalabilidad y altas tasas de conversión."}'::jsonb,
   '{"en": "From custom business sites to complex web applications, we build digital experiences that perform.", "de": "Von individuellen Business-Websites bis hin zu komplexen Webanwendungen erstellen wir digitale Erlebnisse, die funktionieren.", "fr": "Des sites d entreprises aux applications web complexes, nous créons des expériences numériques performantes.", "es": "Desde sitios empresariales personalizados hasta aplicaciones web complejas, creamos experiencias digitales que funcionan."}'::jsonb,
   '{"en": ["Custom Websites", "E-commerce Solutions", "Web Applications", "CMS Integration"], "de": ["Individuelle Websites", "E-Commerce-Lösungen", "Webanwendungen", "CMS-Integration"], "fr": ["Sites web sur mesure", "Solutions e-commerce", "Applications web", "Intégration CMS"], "es": ["Sitios web a medida", "Soluciones de comercio electrónico", "Aplicaciones web", "Integración de CMS"]}'::jsonb,
   'Code',
   '{"en": "Learn More", "de": "Mehr erfahren", "fr": "En savoir plus", "es": "Saber más"}'::jsonb,
   '/services/website-development',
   2,
   true,
   true,
   'published'
  ),
  ('ai-automation',
   '{"en": "AI & Automation", "de": "KI & Automatisierung", "fr": "IA et automatisation", "es": "IA y automatización"}'::jsonb,
   '{"en": "Intelligent systems that automate repetitive work, improve customer communication, and boost operational efficiency.", "de": "Intelligente Systeme, die wiederkehrende Aufgaben automatisieren, die Kundenkommunikation verbessern und Abläufe effizienter gestalten.", "fr": "Des systèmes intelligents qui automatisent les tâches répétitives, améliorent la communication client et renforcent l’efficacité opérationnelle.", "es": "Sistemas inteligentes que automatizan tareas repetitivas, mejoran la comunicación con los clientes y aumentan la eficiencia operativa."}'::jsonb,
   '{"en": "We build AI-powered chatbots, FAQ assistants, workflow automation, and custom integrations that save time and improve efficiency.", "de": "Wir erstellen KI-gestützte Chatbots, FAQ-Assistenten, Workflow-Automatisierung und individuelle Integrationen, die Zeit sparen und die Effizienz verbessern.", "fr": "Nous créons des chatbots IA, des assistants FAQ, l automatisation des workflows et des intégrations sur mesure qui font gagner du temps et améliorent l efficacité.", "es": "Creamos chatbots con IA, asistentes de FAQ, automatización de flujos de trabajo e integraciones personalizadas que ahorran tiempo y mejoran la eficiencia."}'::jsonb,
   '{"en": ["AI Chatbots & Assistants", "Customer Support Automation", "Lead Qualification", "Workflow Automation"], "de": ["KI-Chatbots und -Assistenten", "Automatisierung im Kundenservice", "Lead-Qualifizierung", "Workflow-Automatisierung"], "fr": ["Chatbots et assistants IA", "Automatisation du service client", "Qualification des prospects", "Automatisation des processus"], "es": ["Chatbots y asistentes de IA", "Automatización de la atención al cliente", "Cualificación de clientes potenciales", "Automatización de flujos de trabajo"]}'::jsonb,
   'Brain',
   '{"en": "Learn More", "de": "Mehr erfahren", "fr": "En savoir plus", "es": "Saber más"}'::jsonb,
   '/contact',
   3,
   true,
   true,
   'published'
  ),
  ('growth-marketing',
   '{"en": "Growth & Marketing", "de": "Wachstum & Marketing", "fr": "Croissance et marketing", "es": "Crecimiento y marketing"}'::jsonb,
   '{"en": "Data-driven strategies designed to increase visibility, attract qualified audiences, and drive measurable growth.", "de": "Datenbasierte Strategien, die Ihre Sichtbarkeit erhöhen, qualifizierte Zielgruppen erreichen und messbares Wachstum fördern.", "fr": "Des stratégies fondées sur les données pour accroître votre visibilité, atteindre des audiences qualifiées et générer une croissance mesurable.", "es": "Estrategias basadas en datos para aumentar su visibilidad, atraer audiencias cualificadas e impulsar un crecimiento medible."}'::jsonb,
   '{"en": "From SEO to performance marketing, we develop strategies that deliver measurable results and sustainable growth.", "de": "Von SEO bis Performance-Marketing entwickeln wir Strategien, die messbare Ergebnisse und nachhaltiges Wachstum liefern.", "fr": "Du SEO au marketing de performance, nous développons des stratégies qui offrent des résultats mesurables et une croissance durable.", "es": "Desde SEO hasta marketing de rendimiento, desarrollamos estrategias que ofrecen resultados medibles y crecimiento sostenible."}'::jsonb,
   '{"en": ["SEO", "SEM", "Performance Marketing", "Content Strategy"], "de": ["Suchmaschinenoptimierung (SEO)", "Suchmaschinenmarketing (SEM)", "Performance-Marketing", "Content-Strategie"], "fr": ["Référencement naturel (SEO)", "Référencement payant (SEA)", "Marketing à la performance", "Stratégie de contenu"], "es": ["Optimización para buscadores (SEO)", "Marketing en buscadores (SEM)", "Marketing de resultados", "Estrategia de contenidos"]}'::jsonb,
   'TrendingUp',
   '{"en": "Learn More", "de": "Mehr erfahren", "fr": "En savoir plus", "es": "Saber más"}'::jsonb,
   '/contact',
   4,
   true,
   true,
   'published'
  )
