-- Process Steps
-- =============================================================================

INSERT INTO public.process_steps (step_key, number, title_translations, description_translations, icon_name, display_order, is_visible)
VALUES
  ('discovery', 1,
   '{"en": "Discovery", "de": "Analyse", "fr": "Découverte", "es": "Descubrimiento"}'::jsonb,
   '{"en": "We examine your goals, audience, and challenges to establish a clear foundation for every decision.", "de": "Wir analysieren Ihre Ziele, Zielgruppen und Herausforderungen, um eine klare Grundlage für jede Entscheidung zu schaffen.", "fr": "Nous analysons vos objectifs, votre audience et vos défis afin d'établir une base claire pour chaque décision.", "es": "Analizamos sus objetivos, su público y sus desafíos para establecer una base clara para cada decisión."}'::jsonb,
   'search',
   1,
   true
  ),
  ('strategy', 2,
   '{"en": "Strategy", "de": "Strategie", "fr": "Stratégie", "es": "Estrategia"}'::jsonb,
   '{"en": "We create an integrated strategy across brand, web, AI, and growth, aligned with your business objectives.", "de": "Wir entwickeln eine integrierte Strategie für Marke, Web, KI und Wachstum, abgestimmt auf Ihre Geschäftsziele.", "fr": "Nous élaborons une stratégie intégrée couvrant la marque, le web, l'IA et la croissance, en accord avec vos objectifs commerciaux.", "es": "Creamos una estrategia integrada que abarca marca, web, IA y crecimiento, alineada con sus objetivos empresariales."}'::jsonb,
   'lightbulb',
   2,
   true
  ),
  ('execution', 3,
   '{"en": "Build", "de": "Umsetzung", "fr": "Réalisation", "es": "Desarrollo"}'::jsonb,
   '{"en": "We turn strategy into brand systems, websites, applications, automations, and campaigns, all executed with precision.", "de": "Wir setzen die Strategie in Markensysteme, Websites, Anwendungen, Automatisierungen und Kampagnen um. Dabei arbeiten wir präzise und strukturiert.", "fr": "Nous transformons la stratégie en identités de marque, sites web, applications, automatisations et campagnes, le tout réalisé avec précision.", "es": "Convertimos la estrategia en identidades de marca, sitios web, aplicaciones, automatizaciones y campañas, todo ello ejecutado con precisión."}'::jsonb,
   'settings',
   3,
   true
  ),
  ('growth', 4,
   '{"en": "Launch & Grow", "de": "Launch & Wachstum", "fr": "Lancement et croissance", "es": "Lanzamiento y crecimiento"}'::jsonb,
   '{"en": "We launch, measure, and optimize continuously to improve performance and support sustainable growth.", "de": "Wir bringen Ihr Projekt an den Start, messen die Ergebnisse und optimieren kontinuierlich, um die Leistung zu steigern und nachhaltiges Wachstum zu fördern.", "fr": "Nous assurons le lancement, mesurons les résultats et optimisons en continu afin d'améliorer les performances et de soutenir une croissance durable.", "es": "Lanzamos el proyecto, medimos los resultados y optimizamos continuamente para mejorar el rendimiento e impulsar un crecimiento sostenible."}'::jsonb,
   'rocket',
   4,
   true
  )
ON CONFLICT (step_key) DO UPDATE SET
  number = EXCLUDED.number,
  title_translations = EXCLUDED.title_translations,
  description_translations = EXCLUDED.description_translations,
  icon_name = EXCLUDED.icon_name,
  display_order = EXCLUDED.display_order,
  is_visible = EXCLUDED.is_visible;

